//! M5.5b terminal-preview acceptance after fresh raw PTY fixture replay.
//!
//! The scenario asserts parser-visible text and indexed-color pixels before
//! this module reads its ten PNGs. Bright glyph pixels prove each image has
//! drawn ink beyond the fixed background, while only a human can decide
//! whether the full screenshot looks like a real terminal (R15).
//!
//! The PNGs are regenerated by this criterion before inspection. Otherwise
//! a stale successful image could conceal a current parser or renderer
//! failure. The scenario's `expect-text` checks are independent of ink:
//! they catch a misparsed fixture before a visually plausible frame exists.
//! Counting bright pixels is deliberately coarse. It rejects a clear-only
//! render, while color accuracy is pinned by exact chart pixel assertions
//! in the `.pzs` file and overall appearance remains a review item.
use super::report;
use std::path::Path;

/// Labels expected at both D-27 hinted 1× and unhinted 2× output sizes.
const LABELS: [&str; 5] = ["ls", "git-log", "chart", "box", "vim"];

/// Reports the executable preview scenario as one M5.5b criterion.
pub(super) fn report_preview(passed: &mut bool) {
    report(
        "M5.5b captured terminal previews have ink at 1x and 2x",
        run_and_inspect(),
        passed,
    );
}

/// Replays all recordings before inspecting image bytes, avoiding stale PNGs.
fn run_and_inspect() -> Result<(), String> {
    // Running the harness here makes PNG existence evidence of current code,
    // not of a previous task's files under the ignored target directory.
    crate::commands::quiet(
        "cargo",
        &[
            "run",
            "-p",
            "puzzle-desktop",
            "--",
            "harness",
            "assets/scenarios/preview.pzs",
        ],
    )?;
    for (index, label) in LABELS.iter().enumerate() {
        // Numbering includes four grid dumps, so the first image of each
        // pair is not simply twice its fixture index.
        let first = [1, 4, 7, 10, 13][index];
        let second = [3, 6, 9, 12, 15][index];
        inspect(&format!("target/harness/preview/{first:03}-{label}-1x.png"))?;
        inspect(&format!(
            "target/harness/preview/{second:03}-{label}-2x.png"
        ))?;
    }
    Ok(())
}

/// Requires white text coverage as well as a valid, nonempty PNG.
fn inspect(path: &str) -> Result<(), String> {
    // The D-14 reader checks dimensions, format and stored stream integrity
    // before any pixel qualifies as ink for this criterion.
    let image = crate::png::read(Path::new(path))?;
    // A colored swatch alone is insufficient: all screenshots must contain
    // at least one ordinary glyph run above the preview's dark background.
    let ink = image
        .pixels
        .chunks_exact(4)
        .filter(|rgba| rgba[0] >= 180 && rgba[1] >= 180 && rgba[2] >= 180)
        .count();
    if ink < 100 {
        Err(format!("{path}: only {ink} bright ink pixels"))
    } else {
        Ok(())
    }
}
